const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');const dir=__dirname;const read=f=>fs.readFileSync(path.join(dir,f),'utf8');
let world=read('world/planet-world.js');
world=world.replace('new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true})','new T.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true})');
world=world.replaceAll('g.visible=day>=4;','').replaceAll('airship.visible=day>=10;','').replaceAll('v.globe.visible=day>=4;','');
const end=world.lastIndexOf('})();');if(end<0)throw Error('World wrapper missing');world=world.slice(0,end)+'\n'+read('stellar-scene.js')+'\n'+world.slice(end);
world=world.replace(read('stellar-scene.js'),read('asset-registry.js')+'\n'+read('stellar-scene.js'));
const marker='starlightSwallows.animate(reduced?0:t);';if(!world.includes(marker))throw Error('Animation hook missing');world=world.replace(marker,marker+'window.stellarScene?.tick(dt);');
world=world.replace('const w=host.clientWidth,h=host.clientHeight;camera.aspect','const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;camera.aspect');
world=read("planet-palettes.js")+"\nlet lastH5Frame=0;\n"+world;
world=world.replace('function render(){requestAnimationFrame(render);const dt=',"function render(){requestAnimationFrame(render);if(document.hidden||window.HerstoryHostVisible===false||(document.body.dataset.tab==='mine'&&document.body.dataset.planetMode==='2d')||document.querySelector('#reports-view')?.open||document.querySelector('#growth-summary')?.open||document.querySelector('#planet-card')?.open||!['field','mine'].includes(document.body.dataset.tab)){clock.getDelta();return;}const now=performance.now(),frameBudget=innerWidth<800&&document.body.dataset.tab==='field'?1000/30:0;if(now-lastH5Frame<frameBudget)return;lastH5Frame=now;const dt=");
const sourceConfig=JSON.parse(fs.readFileSync(path.resolve(dir,'../../backend/activity-config/activity-config.json'),'utf8'));
const activityConfig={campaign:sourceConfig.campaign,categories:sourceConfig.categories,activities:sourceConfig.activities.map(({activity_id,event_date,title,category,enabled,track_id,fixed_round,canonical_session_id,starts_at,ended_at,status,kind})=>({activity_id,event_date,title,category,enabled,track_id,fixed_round,canonical_session_id,starts_at,ended_at,status,kind}))};
const manifest=JSON.parse(fs.readFileSync(path.resolve(dir,'../../../..','config/planet_asset_manifest_v1.json'),'utf8'));
const sha=value=>require('node:crypto').createHash('sha256').update(value).digest('hex');
if(sha(read('world/planet-world.js'))!==manifest.worldSha256||sha(read('asset-registry.js'))!==manifest.registrySha256)throw Error('Model changed: re-audit and publish a new manifest before building');
world='window.HERSTORY_ASSET_MANIFEST='+JSON.stringify({modelVersion:manifest.modelVersion,units:manifest.units.map(({id,path})=>({id,path}))})+';\n'+world;
const ui='window.HERSTORY_ACTIVITY_CONFIG=window.HERSTORY_ACTIVITY_CONFIG||'+JSON.stringify(activityConfig)+';\n'+read('report-model.js')+'\n'+read('report-export.js')+'\n'+read('planet-identity.js')+'\n'+read('modal-navigation.js')+'\n'+read('pixel-planet-renderer.js')+'\n'+read('website-pixel.js')+'\n'+read('minimal-page.js')+'\n'+read('sharing-page.js')+'\n'+read('planet-photo.js')+'\n'+read('host-integration.js');new vm.Script(world);new vm.Script(ui);
const html=read('templates/minimal-page.html').replace('<!-- STYLE -->',()=>'<style>'+read('minimal-page.css')+read('report-page.css')+read('host-integration.css')+'</style>').replace('<!-- WORLD -->',()=>'<script>'+world+'</script>').replace('<!-- UI -->',()=>'<script>'+ui+'</script>');
for(const name of ['Herstory-星域-H5.html'])fs.writeFileSync(path.join(dir,name),html);console.log('Built starfield H5 and updated existing minimal page.');
